"use client";

import * as React from "react";

type DriverInstance = {
  setSteps: (steps: unknown[]) => void;
  drive: (step?: number) => void;
  destroy: () => void;
  moveNext: () => void;
  movePrevious: () => void;
};

export type TourStep = {
  element: string; // CSS selector
  title: string;
  description: string;
  side?: "top" | "right" | "bottom" | "left";
  align?: "start" | "center" | "end";
};

type Props = {
  open: boolean;
  steps: TourStep[];
  storageKey?: string;
  onComplete?: () => void;
  onSkip?: () => void;
};

/**
 * Wraps driver.js. Lazy-imported so it only loads when the tour actually runs.
 */
export function OnboardingTour({
  open,
  steps,
  storageKey = "moneytrees:tour:step",
  onComplete,
  onSkip,
}: Props) {
  const driverRef = React.useRef<DriverInstance | null>(null);

  React.useEffect(() => {
    if (!open || typeof window === "undefined") return;
    let cancelled = false;

    (async () => {
      const mod = await import("driver.js");
      // @ts-ignore -- CSS side-effect import: resolvable under moneytrees's
      // vite types but not this package's own tsc context, so expect-error
      // is "unused" in one and required in the other. ts-ignore fits both.
      await import("driver.js/dist/driver.css");
      if (cancelled) return;
      const driver = mod.driver;

      const startStep = Number(localStorage.getItem(storageKey) ?? "0") || 0;

      const handleComplete = () => {
        localStorage.removeItem(storageKey);
        driverRef.current?.destroy();
        driverRef.current = null;
        onComplete?.();
      };

      const handleSkip = () => {
        localStorage.removeItem(storageKey);
        driverRef.current?.destroy();
        driverRef.current = null;
        onSkip?.();
      };

      const instance = driver({
        showProgress: true,
        allowClose: true,
        animate: true,
        smoothScroll: true,
        nextBtnText: "Next →",
        prevBtnText: "← Back",
        doneBtnText: "Done",
        progressText: "{{current}} / {{total}}",
        onCloseClick: handleSkip,
        onDestroyStarted: () => {
          // dismissed by background click / esc
          if (driverRef.current) handleSkip();
        },
        steps: steps.map((s, i) => ({
          element: s.element,
          popover: {
            title: s.title,
            description: s.description,
            side: s.side ?? "right",
            align: s.align ?? "start",
            onNextClick: () => {
              const next = i + 1;
              if (next >= steps.length) {
                handleComplete();
              } else {
                localStorage.setItem(storageKey, String(next));
                instance.moveNext();
              }
            },
            onPrevClick: () => {
              const prev = Math.max(0, i - 1);
              localStorage.setItem(storageKey, String(prev));
              instance.movePrevious();
            },
          },
        })),
      }) as DriverInstance;

      driverRef.current = instance;
      instance.drive(Math.min(startStep, steps.length - 1));
    })();

    return () => {
      cancelled = true;
      driverRef.current?.destroy();
      driverRef.current = null;
    };
  }, [open, steps, storageKey, onComplete, onSkip]);

  return null;
}
